companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page: page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

# Digits-only helper via regex
results = for contact in contacts {
    phone_fixed = false
    company_filled = false
    new_phone = null
    new_company = null

    # Fix phone if present and not E.164
    phone = contact.phone if "phone" in contact else null
    if phone != null {
        # Valid: +1 followed by exactly 10 digits
        valid = regex.test(phone, "^\\+1\\d{10}$")
        if not valid {
            # Extract digits
            digits_list = regex.find_all(phone, "\\d")
            digits = text.join(digits_list, "")
            # If 11 digits starting with 1, use last 10; if 10 digits, use them; else try what we can
            normalized = if text.length(digits) == 11 and text.starts_with(digits, "1") {
                return "+1" + text.slice(digits, 1, 11)
            } else if text.length(digits) == 10 {
                return "+1" + digits
            } else if text.length(digits) > 10 and text.starts_with(digits, "1") {
                return "+1" + text.slice(digits, 1, 11)
            } else if text.length(digits) >= 10 {
                return "+1" + text.slice(digits, text.length(digits) - 10, text.length(digits))
            } else {
                return "+1" + digits
            }
            new_phone = normalized
            phone_fixed = true
        }
    }

    # Fill company if empty
    company = contact.company if "company" in contact else null
    email = contact.email if "email" in contact else null
    needs_company = company == null or company == ""
    if needs_company and email != null {
        parts = text.split(email, "@")
        if list.length(parts) >= 2 {
            domain = parts[1]
            if domain in domain_map {
                new_company = domain_map[domain]
                company_filled = true
            }
        }
    }

    updated = false
    if phone_fixed or company_filled {
        u = update_contact({
            id: contact.id,
            phone: new_phone if phone_fixed else null,
            company: new_company if company_filled else null
        })
        updated = true
    }

    return {
        phone_fixed: phone_fixed,
        company_filled: company_filled
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed: phones_fixed, companies_filled: companies_filled, submit: submit }

