results = for contact in contacts {
    phone = contact.phone if "phone" in contact else null
    email = contact.email if "email" in contact else null
    company = contact.company if "company" in contact else null

    phone_info = if phone != null and not regex.test(phone, "^\\+1\\d{10}$") {
        digits_list = regex.find_all(phone, "\\d")
        digits = text.join(digits_list, "")
        len = text.length(digits)
        normalized = if len == 11 and text.starts_with(digits, "1") {
            return "+1" + text.slice(digits, 1, 11)
        } else if len == 10 {
            return "+1" + digits
        } else if len > 11 and text.starts_with(digits, "1") {
            return "+1" + text.slice(digits, 1, 11)
        } else if len > 10 {
            return "+1" + text.slice(digits, len - 10, len)
        } else {
            return "+1" + digits
        }
        return { fix: true, value: normalized }
    } else {
        return { fix: false, value: null }
    }

    company_info = if (company == null or company == "") and email != null {
        parts = text.split(email, "@")
        info = if list.length(parts) >= 2 {
            domain = parts[1]
            found = if domain in domain_map {
                return { fill: true, value: domain_map[domain] }
            } else {
                return { fill: false, value: null }
            }
            return found
        } else {
            return { fill: false, value: null }
        }
        return info
    } else {
        return { fill: false, value: null }
    }

    did_update = if phone_info.fix or company_info.fill {
        u = boundary retry 3 {
            return update_contact({
                id: contact.id,
                phone: phone_info.value if phone_info.fix else null,
                company: company_info.value if company_info.fill else null
            })
        } catch err {
            return fail("U", err.message)
        }
        return true
    } else {
        return false
    }

    return {
        phone_fixed: phone_info.fix,
        company_filled: company_info.fill,
        id: contact.id
    }
}

